import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"How I Use Claude Code","description":"Boris Tane 的纪律化工作流：research.md → plan.md → 注释循环 → todo → 一次性实施——把思考和打字分开。","frontmatter":{"title":"How I Use Claude Code","description":"Boris Tane 的纪律化工作流：research.md → plan.md → 注释循环 → todo → 一次性实施——把思考和打字分开。","domain":"tech","tags":["tech","course-notes","legacy","claude-code","workflow"],"navOrder":82,"topicId":"course-notes-how-i-use-claude-code","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/course-notes/how-i-use-claude-code.md","filePath":"zh/tech/appendices/course-notes/how-i-use-claude-code.md","lastUpdated":1791165915000}'),s={name:"zh/tech/appendices/course-notes/how-i-use-claude-code.md"};function l(i,e,r,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-i-use-claude-code" tabindex="-1">How I Use Claude Code <a class="header-anchor" href="#how-i-use-claude-code" aria-label="Permalink to &quot;How I Use Claude Code&quot;">​</a></h1><blockquote><p>原文: <a href="https://boristane.com/blog/how-i-use-claude-code/" target="_blank" rel="noreferrer">https://boristane.com/blog/how-i-use-claude-code/</a> （作者 Boris Tane，约 9 个月的主用经验）</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><strong>核心原则</strong>：在你审查并批准书面计划之前，永远不要让 Claude 写代码。「计划与执行分离」是整个工作流最重要的原则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research → Plan → Annotate（循环 1-6 次）→ Todo List → Implement → Feedback &amp; Iterate</span></span></code></pre></div><h2 id="phase-1-research-研究" tabindex="-1">Phase 1: Research（研究） <a class="header-anchor" href="#phase-1-research-研究" aria-label="Permalink to &quot;Phase 1: Research（研究）&quot;">​</a></h2><p>每个有意义的任务从深度阅读开始：让 Claude 彻底理解代码库相关部分，并把发现写入<strong>持久化的 research.md</strong>，而非对话中口头总结。</p><ul><li>指令要用 &quot;deeply&quot;、&quot;in great details&quot;、&quot;go through everything&quot; 这类词——没有它们 Claude 会泛读</li><li><strong>research.md 是作者的审查面</strong>：在任何规划发生之前阅读验证、纠正误解。研究错了 → 计划错 → 实现错。AI 辅助编程最昂贵的失败模式不是语法错误，而是孤立工作但在周围系统中造成破坏的实现</li></ul><h2 id="phase-2-planning-规划" tabindex="-1">Phase 2: Planning（规划） <a class="header-anchor" href="#phase-2-planning-规划" aria-label="Permalink to &quot;Phase 2: Planning（规划）&quot;">​</a></h2><p>研究被审查后，请求详细实施计划写入 <strong>plan.md</strong>（解释方法、代码片段、将修改的文件路径、权衡）。用自建 .md 文件而非内置 plan mode——完全控制权、可内联注释、作为 artifact 持久化。</p><p>实用技巧：见过好的开源实现就把那段代码作为参考分享，Claude 有具体参照时效果显著更好。</p><h2 id="注释循环-annotation-cycle" tabindex="-1">注释循环（Annotation Cycle） <a class="header-anchor" href="#注释循环-annotation-cycle" aria-label="Permalink to &quot;注释循环（Annotation Cycle）&quot;">​</a></h2><p>工作流中最独特、增值最大的部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 写 plan.md → 编辑器中审查 → 添加内联注释 → 发回 Claude 更新计划 → 循环直到满意 → 请求 Todo List</span></span></code></pre></div><p>真实注释示例：纠正错误假设（&quot;no — this should be a PATCH, not a PUT&quot;）、补充领域知识（&quot;use drizzle:generate for migrations, not raw SQL&quot;）、拒绝方案（&quot;remove this section entirely&quot;）。关键指令是明确的 <strong>&quot;don&#39;t implement yet&quot;</strong>——没有它 Claude 会自认为计划够好就跳去写代码。</p><p>Markdown 文件是人与 Claude 之间的<strong>共享可变状态</strong>：按自己的节奏思考、精确标注问题位置、重新投入不丢上下文。</p><h2 id="todo-list-与实施" tabindex="-1">Todo List 与实施 <a class="header-anchor" href="#todo-list-与实施" aria-label="Permalink to &quot;Todo List 与实施&quot;">​</a></h2><p>实施前请求细粒度任务分解（同样 &quot;don&#39;t implement yet&quot;），形成进度追踪器。然后一次性实施：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>implement it all. when you&#39;re done with a task or phase, mark it as completed in the plan document.</span></span>
<span class="line"><span>do not stop until all tasks and phases are completed. do not add unnecessary comments or jsdocs,</span></span>
<span class="line"><span>do not use any or unknown types. continuously run typecheck.</span></span></code></pre></div><p><strong>实施应该是无聊的</strong>——所有决策已在注释循环中做出，创造性工作发生在计划阶段，实施是机械的。</p><h2 id="实施中的反馈" tabindex="-1">实施中的反馈 <a class="header-anchor" href="#实施中的反馈" aria-label="Permalink to &quot;实施中的反馈&quot;">​</a></h2><p>角色从架构师转为监督者，修正通常一句话（&quot;You didn&#39;t implement the deduplicateByTitle function.&quot;）。前端视觉问题用截图比描述快；指向参考（&quot;this table should look exactly like the users table&quot;）比从头描述精确。走向错误时不打补丁，直接回退并缩小范围——几乎总比修糟糕方案的结果好。</p><h2 id="单一长会话" tabindex="-1">单一长会话 <a class="header-anchor" href="#单一长会话" aria-label="Permalink to &quot;单一长会话&quot;">​</a></h2><p>研究、规划、实施在一个连续长会话中完成。作者报告未观察到 50% 上下文后的性能下降；上下文满时自动压缩足够，而计划文档作为持久化 artifact 以完整保真度存活。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>Read deeply, write a plan, annotate the plan until it&#39;s right, then let Claude execute the whole thing without stopping, checking types along the way.</p></blockquote><p>没有魔法 prompt，只有一条纪律严明的管道，把思考和打字分开。</p><h2 id="与主线的关系" tabindex="-1">与主线的关系 <a class="header-anchor" href="#与主线的关系" aria-label="Permalink to &quot;与主线的关系&quot;">​</a></h2><p>「计划/执行分离」「持久化 artifact 作为共享状态」与主线 <a href="/zh/tech/06-agent-systems/recovery-hitl.html">恢复与人工批准</a>（HITL 审批点设计）和 <a href="/zh/tech/03-context/context-engineering.html">上下文工程</a>（外部化记忆）直接对应。</p>`,29)])])}const q=a(s,[["render",l]]);export{b as __pageData,q as default};
